// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    address initializer;

    function setUp() public {
        initializer = address(0xA11CE);
        c = new RoundFactory();
        vm.prank(initializer);
        c.initialize();
    }

    function testFuzz_property(address caller) public {
        // Any caller other than the initializer is admissible
        vm.assume(caller != initializer);

        // The stored owner is fixed by initialization, independent of who queries it.
        // Rule: for ANY caller, owner() returns the initializer's address.
        vm.prank(caller);
        assertTrue(c.owner() == initializer);
    }
}
